// SLOT-TRACKING HELPERS
// ══════════════════════════════════════════════════════════
const usedConsSlots  = new Set<string>();
const usedPsicoSlots = new Set<string>();

const CONSS = [C1, C2, C3];

// Per-psychologist available hours
const psiHoras: Record<string, string[]> = {
  [PS_CMEND]:  ["09:00:00","10:00:00","11:00:00","14:00:00","15:00:00"],
  [PS_AFLOR]:  ["09:00:00","10:00:00","11:00:00"],
  [PS_RVARG]:  ["08:00:00","09:00:00","10:00:00","14:00:00","15:00:00"],
  [PS_MQUISP]: ["14:00:00","15:00:00","16:00:00"],
  [PS_JTORR]:  ["08:00:00","09:00:00","10:00:00","14:00:00","15:00:00"],
};

function findSlot(date: string, psicoId: string, hours: string[]): { hora: string; consId: string } | null {
  for (const hora of hours) {
    const pKey = `${date}|${hora}|${psicoId}`;
    if (usedPsicoSlots.has(pKey)) continue;
    for (const consId of CONSS) {
      const cKey = `${date}|${hora}|${consId}`;
      if (!usedConsSlots.has(cKey)) {
        usedConsSlots.add(cKey);
        usedPsicoSlots.add(pKey);
        return { hora, consId };
      }
    }
  }
  return null;
}

